  function mapPhrase(cat) {
    return byCat(cat).map(function (p) {
      return { en: p.en, zh: p.zh, tag: (p.year || "") + (p.tag ? " · " + p.tag : "") };
    });
  }
  var VERB_PHRASES = mapPhrase("verb-phrase");
